{
  "description": "Summarise a whole week of the calendar.",
  "async": true,
  "parameters": {
    "type": "object",
    "properties": {
      "start_date": {
        "type": "string",
        "description": "First day of the week to summarise, as YYYY-MM-DD."
      }
    },
    "required": [
      "start_date"
    ]
  }
}

parameters.jsCode:
const b = $input.first().json.body || {};
const m = String(b.start_date || '').match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
const now = new Date();
const start = m ? new Date(+m[1], +m[2]-1, +m[3]) : new Date(now.getFullYear(), now.getMonth(), now.getDate());
start.setHours(0,0,0,0);
const end = new Date(start); end.setDate(end.getDate()+7);
return [{ json: { timeMin: start.toISOString(), timeMax: end.toISOString(),
                  label: start.toLocaleDateString('en-GB',{day:'numeric',month:'long'}),
                  callbackUrl: b.__callback_url } }];

const meta = $('Week').first().json;
const events = $input.all().filter(i => i.json && i.json.start);

const byDay = {};
let totalMinutes = 0;
for (const i of events) {
  const e = i.json;
  const s = new Date(e.start.dateTime || e.start.date);
  const key = s.toLocaleDateString('en-GB', { weekday: 'long' });
  byDay[key] = (byDay[key] || 0) + 1;
  if (e.start.dateTime && e.end?.dateTime) {
    totalMinutes += (new Date(e.end.dateTime) - new Date(e.start.dateTime)) / 60000;
  }
}

const days = Object.entries(byDay).sort((a,b) => b[1]-a[1]);
const hours = (totalMinutes / 60).toFixed(1);
const names = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const clear = names.filter(n => !byDay[n]);

let message;
if (!events.length) {
  message = `Nothing scheduled in the week from ${meta.label}.`;
} else {
  const bits = [`${events.length} events in the week from ${meta.label}`,
                `about ${hours} hours booked`];
  if (days.length) bits.push(`busiest day is ${days[0][0]} with ${days[0][1]}`);
  if (clear.length) bits.push(`${clear.slice(0,3).join(' and ')} ${clear.length===1?'is':'are'} clear`);
  message = bits.join(', ') + '.';
}
return [{ json: { result: { message, events: events.length, hours: Number(hours),
                            busiest: days[0] || null, clearDays: clear },
                  callbackUrl: meta.callbackUrl } }];
